    let lowering = MyTxTaylor51::new_ruleset("lowering");
    // A small, typed port of the `lowering` ruleset needed by this benchmark.
    // Note: this intentionally covers only the ops reachable from the seed program.

    MyTxTaylor51::add_rule(
        "t51_lower_var_binary64",
        lowering,
        || {
            let v = T51Var::query();
            let lower = T51Lower::query(&v).a1(&"binary64".to_owned());
            #[eggplant::pat_vars_catch]
            struct Pat {
                v: T51Var,
                lower: T51Lower,
            }
        },
        |ctx, pat| {
            let name = ctx.devalue(pat.v.a0);
            let out = ctx.insert_t51_varbinary64(name);
            ctx.union(pat.lower, out);
        },
    );

